SELECT CASE WHEN budget >= 3682000 THEN 'high' WHEN budget >= 983000 THEN 'mid' ELSE 'low' END AS budget_bucket, SUM(CASE WHEN location = 'Berlin' THEN 1 ELSE 0 END) AS berlin_count, SUM(CASE WHEN location = 'Singapore' THEN budget ELSE 0 END) AS singapore_budget FROM departments WHERE location != 'Singapore' GROUP BY CASE WHEN budget >= 3682000 THEN 'high' WHEN budget >= 983000 THEN 'mid' ELSE 'low' END ORDER BY singapore_budget DESC
